		*blk_size = BIT(allocator->info.blk_sz_shift);
	}

out:
	return ret;

int i;
	int ret = 0;
	sys_mem_blocks_t *allocator = NULL;

	__ASSERT_NO_MSG(group != NULL);
	__ASSERT_NO_MSG(in_blocks != NULL);

	if (count == 0) {
		goto out;
	}

	for (i = 0; i < group->num_allocators; i++) {
		/*
		 * Find out which allocator the allocated blocks
		 * belong to.
		 */

		uint8_t *start, *end;
		sys_mem_blocks_t *one_alloc;

		one_alloc = group->allocators[i];
		start = one_alloc->buffer;
		end = start + (BIT(one_alloc->info.blk_sz_shift) *
			       one_alloc->info.num_blocks);

		if (((uint8_t *)in_blocks[0] >= start) &&
		    ((uint8_t *)in_blocks[0] < end)) {
			allocator = one_alloc;
			break;
		}
	}

	if (allocator != NULL) {
		ret = sys_mem_blocks_free(allocator, count, in_blocks);
	} else {
		ret = -EINVAL;
	}

out:
	return ret;

ARG_UNUSED(desc);

	/* Has effect only on first register */
	bos_hdr.wTotalLength = usb_bos_get_length();

	bos_hdr.bNumDeviceCaps += 1U;

int ret;
	struct usb_dc_ep_cfg_data ep0_cfg;
	struct usb_device_descriptor *dev_desc;

	/* Prevent from calling usb_enable form different context.
	 * This should only be called once.
	 */
	LOG_DBG("lock usb_enable_lock mutex");
	k_mutex_lock(&usb_enable_lock, K_FOREVER);

	if (usb_dev.enabled == true) {
		LOG_WRN("USB device support already enabled");
		ret = -EALREADY;
		goto out;
	}

	/*
	 * If usb_dev.descriptors is equal to NULL (usb_dev has static
	 * specifier), then usb_get_device_descriptor() and usb_set_config()
	 * are likely not called yet. If so, set the configuration here.
	 */
	if (usb_dev.descriptors == NULL) {
		usb_set_config(usb_get_device_descriptor());
		if (usb_dev.descriptors == NULL) {
			LOG_ERR("Failed to configure USB device stack");
			ret =  -1;
			goto out;
		}
	}

	/* Enable VBUS if needed */
	ret = usb_vbus_set(true);
	if (ret < 0) {
		goto out;
	}

	dev_desc = (void *)usb_dev.descriptors;
	usb_dev.user_status_callback = status_cb;
	usb_register_status_callback(forward_status_cb);
	usb_dc_set_status_callback(forward_status_cb);

	ret = usb_dc_attach();
	if (ret < 0) {
		goto out;
	}

	ret = usb_transfer_init();
	if (ret < 0) {
		goto out;
	}

	if (dev_desc->bDescriptorType != USB_DESC_DEVICE ||
	    dev_desc->bMaxPacketSize0 == 0) {
		LOG_ERR("Erroneous device descriptor or bMaxPacketSize0");
		ret = -EINVAL;
		goto out;
	}

	/* Configure control EP */
	usb_dev.mps0 = dev_desc->bMaxPacketSize0;
	ep0_cfg.ep_mps = usb_dev.mps0;
	ep0_cfg.ep_type = USB_DC_EP_CONTROL;

	ep0_cfg.ep_addr = USB_CONTROL_EP_OUT;
	ret = usb_dc_ep_configure(&ep0_cfg);
	if (ret < 0) {
		goto out;
	}

	ep0_cfg.ep_addr = USB_CONTROL_EP_IN;
	ret = usb_dc_ep_configure(&ep0_cfg);
	if (ret < 0) {
		goto out;
	}

	/* Register endpoint 0 handlers*/
	ret = usb_dc_ep_set_callback(USB_CONTROL_EP_OUT,
				     usb_handle_control_transfer);
	if (ret < 0) {
		goto out;
	}

	ret = usb_dc_ep_set_callback(USB_CONTROL_EP_IN,
				     usb_handle_control_transfer);
	if (ret < 0) {
		goto out;
	}

	/* Register endpoint handlers*/
	ret = composite_setup_ep_cb();
	if (ret < 0) {
		goto out;
	}

	/* Enable control EP */
	ret = usb_dc_ep_enable(USB_CONTROL_EP_OUT);
	if (ret < 0) {
		goto out;
	}
	usb_dev.ep_bm |= get_ep_bm_from_addr(USB_CONTROL_EP_OUT);

	ret = usb_dc_ep_enable(USB_CONTROL_EP_IN);
	if (ret < 0) {
		goto out;
	}
	usb_dev.ep_bm |= get_ep_bm_from_addr(USB_CONTROL_EP_IN);

	usb_dev.enabled = true;
	ret = 0;
out:
	LOG_DBG("unlock usb_enable_lock mutex");
	k_mutex_unlock(&usb_enable_lock);
	return ret;

static bool initialized;

	LOG_DBG("__usb_descriptor_start %p", __usb_descriptor_start);
	LOG_DBG("__usb_descriptor_end %p", __usb_descriptor_end);

	if (!initialized) {
		if (usb_fix_descriptor(__usb_descriptor_start)) {
			LOG_ERR("Failed to fixup USB descriptor");
			return NULL;
		}

		initialized = true;
	}

	return (uint8_t *) __usb_descriptor_start;

struct usb_device_descriptor *hs_desc, *fs_desc;
	int ret = 0;

	usbd_device_lock(uds_ctx);

	hs_desc = uds_ctx->hs_desc;
	if (USBD_SUPPORTS_HIGH_SPEED && hs_desc == NULL) {
		ret = -EPERM;
		goto add_descriptor_error;
	}

	fs_desc = uds_ctx->fs_desc;
	if (!fs_desc || usbd_is_initialized(uds_ctx)) {
		ret = -EPERM;
		goto add_descriptor_error;
	}

	/* Check if descriptor list is initialized */
	if (!sys_dnode_is_linked(&uds_ctx->descriptors)) {
		LOG_DBG("Initialize descriptors list");
		sys_dlist_init(&uds_ctx->descriptors);
	}

	if (sys_dnode_is_linked(&desc_nd->node)) {
		ret = -EALREADY;
		goto add_descriptor_error;
	}

	if (IS_ENABLED(CONFIG_USBD_BOS_SUPPORT) &&
	    desc_nd->bDescriptorType == USB_DESC_BOS) {
		if (IS_ENABLED(CONFIG_USBD_VREQ_SUPPORT) &&
		    desc_nd->bos.utype == USBD_DUT_BOS_VREQ) {
			ret =  usbd_device_register_vreq(uds_ctx, desc_nd->bos.vreq_nd);
			if (ret) {
				goto add_descriptor_error;
			}
		}

		sys_dlist_append(&uds_ctx->descriptors, &desc_nd->node);
	}

	if (desc_nd->bDescriptorType == USB_DESC_STRING) {
		ret = desc_add_and_update_idx(uds_ctx, desc_nd);
		if (ret) {
			ret = -EINVAL;
			goto add_descriptor_error;
		}

		switch (desc_nd->str.utype) {
		case USBD_DUT_STRING_LANG:
			break;
		case USBD_DUT_STRING_MANUFACTURER:
			if (USBD_SUPPORTS_HIGH_SPEED) {
				hs_desc->iManufacturer = desc_nd->str.idx;
			}

			fs_desc->iManufacturer = desc_nd->str.idx;
			break;
		case USBD_DUT_STRING_PRODUCT:
			if (USBD_SUPPORTS_HIGH_SPEED) {
				hs_desc->iProduct = desc_nd->str.idx;
			}

			fs_desc->iProduct = desc_nd->str.idx;
			break;
		case USBD_DUT_STRING_SERIAL_NUMBER:
			if (USBD_SUPPORTS_HIGH_SPEED) {
				hs_desc->iSerialNumber = desc_nd->str.idx;
			}

			fs_desc->iSerialNumber = desc_nd->str.idx;
			break;
		default:
			break;
		}
	}

add_descriptor_error:
	usbd_device_unlock(uds_ctx);
	return ret;

bool ep0_empty;
	int ret;

	k_sched_lock();
	usbd_device_lock(uds_ctx);

	if (!usbd_is_initialized(uds_ctx)) {
		LOG_WRN("USB device support is not initialized");
		ret = -EPERM;
		goto enable_exit;
	}

	if (usbd_is_enabled(uds_ctx)) {
		LOG_WRN("USB device support is already enabled");
		ret = -EALREADY;
		goto enable_exit;
	}

	/* UDC drivers can keep enqueued control buffers across disable/enable
	 * cycle. Enqueue SETUP buffer only if there are no queued buffers.
	 * This check has to be done before udc_enable(), because only before
	 * enable the driver won't complete any queued buffer.
	 */
	ep0_empty = udc_ep_queue_is_empty(uds_ctx->dev, USB_CONTROL_EP_OUT);

	ret = udc_enable(uds_ctx->dev);
	if (ret != 0) {
		LOG_ERR("Failed to enable controller");
		goto enable_exit;
	}

	ret = usbd_preallocate(uds_ctx);
	if (ret != 0) {
		LOG_ERR("Buffer preallocation failed");
		udc_disable(uds_ctx->dev);
		goto enable_exit;
	}

	ret = usbd_init_control_pipe(uds_ctx, ep0_empty);
	if (ret != 0) {
		udc_disable(uds_ctx->dev);
		goto enable_exit;
	}

	uds_ctx->status.enabled = true;

enable_exit:
	usbd_device_unlock(uds_ctx);
	k_sched_unlock();

	return ret;

sys_dnode_t *const node = sys_dlist_peek_head(&uhs_ctx->udevs);
	struct usb_device *udev;

	udev = SYS_DLIST_CONTAINER(node, udev, node);

	return udev;

struct usb_setup_packet req = {
		.bmRequestType = bmRequestType,
		.bRequest = bRequest,
		.wValue = sys_cpu_to_le16(wValue),
		.wIndex = sys_cpu_to_le16(wIndex),
		.wLength = sys_cpu_to_le16(wLength),
	};
	struct uhc_transfer *xfer;
	uint8_t ep = usb_reqtype_is_to_device(&req) ? 0x00 : 0x80;
	int ret;

	xfer = usbh_xfer_alloc(udev, ep, ch9_req_cb, NULL);
	if (!xfer) {
		return -ENOMEM;
	}

	memcpy(xfer->setup_pkt, &req, sizeof(req));

	__ASSERT(IS_ENABLED(CONFIG_ZTEST) ||
		 (buf != NULL && wLength) || (buf == NULL && !wLength),
		 "Unresolved conditions for data stage");
	if (wLength) {
		ret = usbh_xfer_buf_add(udev, xfer, buf);
		if (ret) {
			goto buf_alloc_err;
		}
	}

	if (IS_ENABLED(CONFIG_ZTEST) && ctrl_req_no_status) {
		xfer->no_status = true;
	}

	ret = usbh_xfer_enqueue(udev, xfer);
	if (ret) {
		goto buf_alloc_err;
	}

	if (k_sem_take(&ch9_req_sync, K_MSEC(SETUP_REQ_TIMEOUT)) != 0) {
		ret = usbh_xfer_dequeue(udev, xfer);
		if (ret != 0) {
			LOG_ERR("Failed to cancel transfer");
			return ret;
		}

		LOG_ERR("Timeout");
		return -ETIMEDOUT;
	}

	ret = xfer->err;

buf_alloc_err:
	usbh_xfer_free(udev, xfer);

	return ret;

int rc;
	struct fs_file_t *f = &fs_file;

	if (backend_state == BACKEND_FS_NOT_INITIALIZED) {
		if (check_log_volume_available()) {
			return length;
		}
		rc = create_log_dir(CONFIG_LOG_BACKEND_FS_DIR);
		if (!rc) {
			rc = allocate_new_file(&fs_file);
		}
		backend_state = (rc ? BACKEND_FS_CORRUPTED : BACKEND_FS_OK);
	}

	if (backend_state == BACKEND_FS_OK) {

		/* Check if new data overwrites max file size.
		 * If so, create new log file.
		 */
		int size = fs_tell(f);

		if (size < 0) {
			backend_state = BACKEND_FS_CORRUPTED;

			return length;
		} else if ((size + length) > CONFIG_LOG_BACKEND_FS_FILE_SIZE) {
			rc = allocate_new_file(f);

			if (rc < 0) {
				goto on_error;
			}
		}

		rc = fs_write(f, data, length);
		if (rc >= 0) {
			if (IS_ENABLED(CONFIG_LOG_BACKEND_FS_OVERWRITE) &&
			    (rc != length)) {
				del_oldest_log();

				return 0;
			}
			/* If overwrite is disabled, full memory
			 * cause the log record abandonment.
			 */
			length = rc;
		} else {
			rc = check_log_file_exist(newest);
			if (rc == 0) {
				/* file was lost somehow
				 * try to get a new one
				 */
				file_ctr--;
				rc = allocate_new_file(f);
				if (rc < 0) {
					goto on_error;
				}
			} else if (rc < 0) {
				/* fs is corrupted*/
				goto on_error;
			}
			length = 0;
		}
	}

	return length;

on_error:
	backend_state = BACKEND_FS_CORRUPTED;
	return length;

#ifdef CONFIG_MPSC_PBUF
	mpsc_pbuf_init(&log_buffer, &mpsc_config);
	curr_log_buffer = &log_buffer;
#endif

struct shell_history_item *h_item; /* history item */
	sys_dnode_t *l_item; /* list item */

	if (up) { /* button up */
		l_item = (history->current == NULL) ?
		sys_dlist_peek_head(&history->list) :
		sys_dlist_peek_next_no_check(&history->list, history->current);
	} else { /* button down */
		l_item = sys_dlist_peek_prev(&history->list, history->current);
	}

	history->current = l_item;
	if (l_item == NULL) {
		/* Reached the end of history. */
		*len = 0U;
		return false;
	}

	h_item = CONTAINER_OF(l_item, struct shell_history_item, dnode);
	memcpy(dst, h_item->data, h_item->len);
	*len = h_item->len;
	dst[*len] = '\0';
	return true;

sys_dnode_t *node;
	struct shell_history_item *new, *h_prev_item;
	uint32_t total_len = len + offsetof(struct shell_history_item, data);

	z_shell_history_mode_exit(history);
	if (len == 0) {
		return;
	}

	node = sys_dlist_peek_head(&history->list);
	h_prev_item = CONTAINER_OF(node, struct shell_history_item, dnode);

	if (node &&
	   (h_prev_item->len == len) &&
	   (memcmp(h_prev_item->data, line, len) == 0)) {
		/* Same command as before, do not store */
		return;
	}

	for (;;) {
		new = k_heap_alloc(history->heap, total_len, K_NO_WAIT);
		if (new) {
			/* Got memory, add new item */
			break;
		} else if (!remove_from_tail(history)) {
			/* Nothing to remove, cannot allocate memory. */
			return;
		}
	}

	new->len = len;
	memcpy(new->data, line, len);
	sys_dlist_prepend(&history->list, &new->dnode);

int err;
	struct zbus_observer_node *obs_nd, *tmp;
	struct zbus_observer_node *prev_obs_nd = NULL;

	_ZBUS_ASSERT(!k_is_in_isr(), "ISR blocked");
	_ZBUS_ASSERT(chan != NULL, "chan is required");
	_ZBUS_ASSERT(obs != NULL, "obs is required");

	err = k_sem_take(&chan->data->sem, timeout);
	if (err) {
		return err;
	}

	SYS_SLIST_FOR_EACH_CONTAINER_SAFE(&chan->data->observers, obs_nd, tmp, node) {
		if (obs_nd->obs == obs) {
			sys_slist_remove(&chan->data->observers,
					 prev_obs_nd ? &prev_obs_nd->node : NULL,
					 &obs_nd->node);
#if defined(CONFIG_ZBUS_RUNTIME_OBSERVERS_NODE_ALLOC_NONE)
			obs_nd->chan = NULL;
#else
			_zbus_runtime_observer_node_free(obs_nd);
#endif

			k_sem_give(&chan->data->sem);

			return 0;
		}

		prev_obs_nd = obs_nd;
	}

	k_sem_give(&chan->data->sem);

	return -ENODATA;

_ZBUS_ASSERT(agent != NULL, "Proxy agent configuration is NULL in init");
	_ZBUS_ASSERT(agent->thread_id != NULL, "Thread ID storage is NULL in proxy agent init");
	_ZBUS_ASSERT(agent->backend_api != NULL, "Backend API is NULL in proxy agent init");
	_ZBUS_ASSERT(agent->thread != NULL, "Thread is NULL in proxy agent init");
	_ZBUS_ASSERT(agent->msgq != NULL, "Message queue is NULL in proxy agent init");
	_ZBUS_ASSERT(agent->stack != NULL, "Thread stack is NULL in proxy agent init");

	int ret;

	*agent->thread_id = k_thread_create(
		agent->thread, agent->stack, CONFIG_ZBUS_PROXY_AGENT_WORK_QUEUE_STACK_SIZE,
		proxy_agent_thread_fn, (void *)agent, NULL, NULL,
		CONFIG_ZBUS_PROXY_AGENT_WORK_QUEUE_PRIORITY, 0, K_NO_WAIT);
	k_thread_name_set(*agent->thread_id, agent->name);

	ret = agent->backend_api->backend_set_recv_cb(agent, zbus_proxy_agent_receive_cb);
	if (ret < 0) {
		LOG_ERR("Failed to set receive callback for proxy agent %s: %d", agent->name, ret);
		k_thread_abort(*agent->thread_id);
		*agent->thread_id = NULL;
		return ret;
	}

	ret = agent->backend_api->backend_init(agent);
	if (ret < 0) {
		LOG_ERR("Failed to initialize backend for proxy agent %s: %d", agent->name, ret);
		k_thread_abort(*agent->thread_id);
		*agent->thread_id = NULL;
		return ret;
	}

	LOG_DBG("Proxy agent %s initialized successfully", agent->name);

	return 0;

if (val < r->min) {
		*idx = r->min_idx;
		return -ERANGE;
	}

	if (val > linear_range_get_max_value(r)) {
		*idx = r->max_idx;
		return -ERANGE;
	}

	if (r->step == 0U) {
		*idx = r->min_idx;
	} else {
		*idx = r->min_idx + DIV_ROUND_UP((uint32_t)(val - r->min),
						 r->step);
	}

	return 0;

int32_t r_max = linear_range_get_max_value(r);

	if ((val_max < r->min) || (val_min > r_max)) {
		return -EINVAL;
	}

	if (val_min < r->min) {
		*idx = r->min_idx;
		return -ERANGE;
	}

	if (val_max > r_max) {
		*idx = r->max_idx;
		return -ERANGE;
	}

	if (r->step == 0U) {
		*idx = r->min_idx;
		return 0;
	}

	*idx = r->min_idx + DIV_ROUND_UP((uint32_t)(val_min - r->min), r->step);
	if ((r->min + r->step * (*idx - r->min_idx)) > val_max) {
		return -EINVAL;
	}

	return 0;

__ASSERT_NO_MSG(ts != NULL);
	__ASSERT_NO_MSG(Z_IS_TIMEOUT_RELATIVE(timeout) ||
			(IS_ENABLED(CONFIG_TIMEOUT_64BIT) &&
			 K_TIMEOUT_EQ(timeout, (k_timeout_t){K_TICKS_FOREVER})));

	/* equivalent of K_FOREVER without including kernel.h */
	if (K_TIMEOUT_EQ(timeout, (k_timeout_t){K_TICKS_FOREVER})) {
		/* duration == K_TICKS_FOREVER ticks */
		*ts = SYS_TIMESPEC_FOREVER;
		/* equivalent of K_NO_WAIT without including kernel.h */
	} else if (K_TIMEOUT_EQ(timeout, (k_timeout_t){0})) {
		/* duration <= 0 ticks */
		*ts = SYS_TIMESPEC_NO_WAIT;
	} else {
		*ts = SYS_TICKS_TO_TIMESPEC(timeout.ticks);
	}

	__ASSERT_NO_MSG(timespec_is_valid(ts));

_ZBUS_ASSERT(obs != NULL, "obs is required");
	_ZBUS_ASSERT(enable != NULL, "enable is required");

	*enable = obs->data->enabled;

	return 0;
